/* HACERLO V2.4 · Encuestas y experiencias · scripts clásicos compatibles. */
let eeQuickState=null,eePickerOpen=true;
let eeSelected=null,eeTab='diseño',eeFilter={wave:'',audienceId:''},eeImport=null;
function eeSurvey(){return EE.init(current()).find(s=>s.id===eeSelected);}
function eeMsg(message,error=false){const el=$('ee-message');if(el){el.textContent=message;el.setAttribute('role',error?'alert':'status');}else alert(message);}
function eeDownload(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function eeOpen(id){eePickerOpen=false;eeSelected=id;eeTab='diseño';eeFilter={wave:'',audienceId:''};eeImport=null;render();}
function eeSetTab(tab){eeTab=tab;eeImport=null;render();if(tab==='resultados')eePull(true);}
function eeCreate(e){e.preventDefault();const f=new FormData(e.target),s=EE.create(f.get('kind'),f.get('title').trim());if(!s.title)return;EE.init(current()).push(s);eeSelected=s.id;eePickerOpen=false;save();render();}
function eeOptions(values,selected){return values.map(v=>`<option value="${safe(v)}" ${v===selected?'selected':''}>${safe(v)}</option>`).join('');}
function eeAudienceOptions(x,selected=''){return '<option value="">Todas / sin segmentar</option>'+(x.audiences||[]).map(a=>`<option value="${safe(a.id)}" ${String(a.id)===String(selected)?'selected':''}>${safe(a.name)}</option>`).join('');}
function eePage(x){
 const surveys=EE.init(x);if(!surveys.some(s=>s.id===eeSelected))eeSelected=surveys[0]?.id||null;const s=eeSurvey();
 return `<section class="panel ee-hero ${eePickerOpen?'':'ee-hero-compact'}"><div class="flex" style="justify-content:space-between"><div><span class="pill">V2.6.0 · ${safe(x.name)}</span><h2>Encuestas y experiencias</h2><p class="muted">Escucha, comprende y conecta la evidencia con tus decisiones.</p></div><span class="ee-orbit" aria-hidden="true">◎</span></div><p id="ee-message" role="status"></p></section><div class="ee-layout ${eePickerOpen?'':'ee-focused'}"><section class="panel ee-sidebar" ${eePickerOpen?'':'hidden'}><h3>Instrumentos de la iniciativa</h3>${surveys.map(z=>`<button class="ee-survey ${z.id===s?.id?'selected':''}" onclick="eeOpen('${z.id}')"><b>${safe(z.title)}</b><small>${safe(z.kind)} · v${z.version} · ${safe(z.status)} · ${z.responses.length} respuestas</small></button>`).join('')||'<p class="muted">Crea tu primer instrumento.</p>'}${eeTrashPanel(x)}<h3>Cargar desde Excel</h3><p class="muted">Crea las preguntas y carga las respuestas desde el mismo archivo.</p><input type="file" accept=".xlsx,.csv" onchange="eeQuickRead(this)"><h3>Nuevo instrumento manual</h3><form onsubmit="eeCreate(event)"><label>Plantilla<select name="kind">${eeOptions(['SENTIR','NPS','CNPS','Conocimiento','Libre'],'SENTIR')}</select></label><label>Nombre<input name="title" required maxlength="160" placeholder="Ej. Pulso de adopción · octubre"></label><button class="primary">+ Crear</button></form></section><div>${eeQuickState?eeQuickPanel():''}${s?`<section class="panel"><div class="flex" style="justify-content:space-between"><div><button class="secondary" onclick="eeTogglePicker()">${eePickerOpen?'Ocultar selector':'Cambiar encuesta'}</button><h2>${safe(s.title)}</h2><p class="muted">${safe(s.kind)} · Versión ${s.version} · ${safe(s.status)}</p></div><div class="flex"><button class="secondary" onclick="eeClone()">Duplicar / nueva versión</button><button class="secondary" onclick="eeDeleteSurvey()">Eliminar encuesta</button></div></div>${eeMomentEditor(s)}${eeImportHistory(s)}<details><summary>Cambiar nombre de la encuesta</summary><form onsubmit="eeRenameSurvey(event)"><label>Nombre<input name="title" value="${safe(s.title)}" required maxlength="160"></label><button class="primary">Guardar nombre</button></form></details><div class="flex ee-tabs">${['diseño','responder','importar','resultados','compartir'].map(t=>`<button class="secondary ${eeTab===t?'active':''}" onclick="eeSetTab('${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></section>${eeTab==='diseño'?eeDesigner(x,s)+eeOptionScoringPanel(s):eeTab==='responder'?eeResponsePanel(x,s):eeTab==='importar'?eeImportPanel(s):eeTab==='resultados'?eeResults(x,s):eeSharePanel(s)}`:'<section class="panel empty"><h2>De la experiencia a la evidencia</h2><p>Selecciona SENTIR, NPS, CNPS, Conocimiento o crea una encuesta libre.</p><p>Cada instrumento conserva su iniciativa, versión, audiencia y ola de medición.</p></section>'}</div></div>`;
}
function eeDesigner(x,s){const locked=s.status!=='draft'||s.responses.length>0;if(locked)return eeLockedDesigner(s);return `<section class="panel"><p class="notice">${safe(s.instrumentNote)} SENTIR: 1 = totalmente en desacuerdo, 5 = totalmente de acuerdo. Desgaste alto representa mayor desgaste. NPS y CNPS son medidas diferentes.</p><form onsubmit="eeSaveDesign(event)"><fieldset ${locked?'disabled':''}><label>Nombre<input name="title" value="${safe(s.title)}" required maxlength="160"></label><label>Descripción<textarea name="description">${safe(s.description)}</textarea></label><div class="triple"><label>Audiencia<select name="audienceId">${eeAudienceOptions(x,s.audienceId)}</select></label><label>Ola<input name="wave" value="${safe(s.wave)}" required maxlength="80"></label><label>Período<input name="period" value="${safe(s.period)}" placeholder="Ej. 2026-10"></label></div><h3>Preguntas</h3><p class="muted">Edita textos, tipos y opciones. En Conocimiento define las respuestas correctas. «Invertir» cambia el sentido antes de agregar escalas.</p><div id="ee-questions">${s.questions.map((q,i)=>eeQuestionEditor(q,i)).join('')}</div><button type="button" class="secondary" onclick="eeAddQuestion()">+ Añadir pregunta</button><details><summary>Editor JSON avanzado</summary><p class="muted">Para usar este editor, marca la casilla. Conserva IDs únicos.</p><label><input type="checkbox" name="advanced"> Usar JSON en lugar de las tarjetas</label><textarea name="questionsJSON" rows="14">${safe(JSON.stringify(s.questions,null,2))}</textarea></details><button class="primary">Guardar diseño</button></fieldset></form><div class="flex" style="margin-top:18px">${s.status==='draft'?'<button class="primary" onclick="eeStatus(\'active\')">Activar encuesta</button>':s.status==='active'?'<button class="secondary" onclick="eeStatus(\'closed\')">Cerrar captura</button>':'<button class="secondary" onclick="eeStatus(\'active\')">Reabrir captura</button>'}${locked?'<span class="muted">El diseño está congelado. Duplica para cambiar preguntas.</span>':''}</div></section>`;}
function eeQuestionEditor(q,i){return `<fieldset class="ee-question" data-ee-question><div class="flex" style="justify-content:space-between"><strong>Pregunta ${i+1}</strong><button class="secondary" type="button" onclick="this.closest('[data-ee-question]').remove()">Quitar</button></div><label>Texto<input data-k="label" value="${safe(q.label)}" required></label><div class="triple"><label>ID<input data-k="id" value="${safe(q.id)}" required></label><label>Tipo<select data-k="type">${eeOptions(['scale','nps','cnps','text','choice','knowledge'],q.type)}</select></label><label>Dimensión<input data-k="dimension" value="${safe(q.dimension||'')}"></label><label>Mínimo<input data-k="min" type="number" step="any" value="${q.min??0}"></label><label>Máximo<input data-k="max" type="number" step="any" value="${q.max??10}"></label></div><label>Opciones (una por línea, para choice / knowledge)<textarea data-k="options">${safe((q.options||[]).join('\n'))}</textarea></label><label>Respuesta correcta (knowledge)<input data-k="correct" value="${safe(q.correct||'')}"></label><div class="flex"><label><input data-k="required" type="checkbox" ${q.required?'checked':''}> Obligatoria</label><label><input data-k="reverse" type="checkbox" ${q.reverse?'checked':''}> Invertir escala</label></div></fieldset>`;}
function eeAddQuestion(){const s=eeSurvey();if(s.status!=='draft')return;const el=document.createElement('div');el.innerHTML=eeQuestionEditor({id:'q_'+EE.uid().replaceAll('-','').slice(0,8),label:'',type:'text'},document.querySelectorAll('[data-ee-question]').length);$('ee-questions').append(el.firstElementChild);}
function eeSaveDesign(e){e.preventDefault();const s=eeSurvey();if(s.status!=='draft'||s.responses.length)return;try{const f=new FormData(e.target);let qs;
 if(f.get('advanced'))qs=JSON.parse(f.get('questionsJSON'));else qs=[...e.target.querySelectorAll('[data-ee-question]')].map(el=>{const get=k=>el.querySelector(`[data-k="${k}"]`);let q={id:get('id').value.trim(),label:get('label').value.trim(),type:get('type').value,required:get('required').checked,dimension:get('dimension').value.trim(),reverse:get('reverse').checked};if(['scale','nps','cnps'].includes(q.type)){q.min=Number(get('min').value);q.max=Number(get('max').value);}if(['choice','knowledge'].includes(q.type))q.options=get('options').value.split('\n').map(s=>s.trim()).filter(Boolean);if(q.type==='knowledge')q.correct=get('correct').value.trim();const prior=s.questions.find(v=>v.id===q.id);if(prior?.optionScoring&&['text','choice'].includes(q.type))q.optionScoring=structuredClone(prior.optionScoring);return q;});
 EE.validateQuestions(qs);Object.assign(s,{title:f.get('title').trim(),description:f.get('description'),audienceId:f.get('audienceId'),wave:f.get('wave').trim(),period:f.get('period'),questions:qs,updatedAt:EE.now()});save();render();eeMsg('Diseño guardado.');return true;}catch(err){eeMsg(err.message,true);return false;}}
function eeClone(){const x=current(),s=eeSurvey(),z=structuredClone(s);Object.assign(z,{id:EE.uid(),previousSurveyId:s.id,familyId:s.familyId||s.id,title:s.title+' · nueva versión',version:s.version+1,status:'draft',responses:[],createdAt:EE.now()});delete z.publication;delete z.syncedAt;delete z.metricLinks;delete z.importHistory;delete z.lastImportedAt;EE.init(x).push(z);eeSelected=z.id;eeTab='diseño';save();render();}
async function eeStatus(status){const s=eeSurvey();if(s.status==='draft'){const form=document.querySelector('form[onsubmit="eeSaveDesign(event)"]');if(form&&(!form.reportValidity()||!eeSaveDesign({preventDefault(){},target:form})))return;}try{EE.validateQuestions(s.questions);if(s.publication){eeMsg('Actualizando captura pública…');const {error}=await sb.from('ee_publications').update({active:status==='active'&&!s.publication.revoked}).eq('id',s.publication.id);if(error)throw error;}s.status=status;save();render();}catch(e){eeMsg(e.message,true);}}
function eeQuestionInput(q){const attrs=`name="${safe(q.id)}" ${q.required?'required':''}`;if(q.type==='text')return `<textarea ${attrs} maxlength="5000"></textarea>`;if(['choice','knowledge'].includes(q.type))return `<select ${attrs}><option value="">Seleccionar</option>${eeOptions(q.options,'')}</select>`;return `<input ${attrs} type="number" min="${q.min}" max="${q.max}" step="${q.type==='scale'?'any':'1'}" placeholder="${q.min} a ${q.max}">`;}
function eeResponsePanel(x,s){if(s.status!=='active')return '<section class="panel empty">Activa la encuesta desde Diseño para registrar respuestas.</section>';return `<section class="panel"><h3>Registrar respuesta / experiencia</h3><p class="muted">Captura interna. Para participantes externos usa Compartir.</p><form onsubmit="eeSubmit(event)"><div class="triple"><label>Código o alias opcional<input name="respondent" maxlength="100" placeholder="Sin nombre ni documento"></label><label>Audiencia<select name="audienceId">${eeAudienceOptions(x,s.audienceId)}</select></label><label>Ola<input name="wave" value="${safe(s.wave)}" required maxlength="80"></label></div>${s.questions.map(q=>`<label>${safe(q.label)} ${q.required?'*':''}${eeQuestionInput(q)}</label>`).join('')}<button class="primary">Guardar respuesta</button></form></section>`;}
function eeSubmit(e){e.preventDefault();const s=eeSurvey();if(s.status!=='active')return;const f=Object.fromEntries(new FormData(e.target)),v=EE.validateResponse(s,f);if(v.errors.length){eeMsg(v.errors.join('\n'),true);return;}s.responses.push({id:EE.uid(),date:EE.now(),respondent:f.respondent||'',audienceId:f.audienceId,wave:f.wave,answers:v.answers,source:'internal'});eeIntegrate(current(),s);save();render();eeMsg('Respuesta registrada y evidencia actualizada.');}
function eeIntegrate(x,s){
 const a=EE.summarize(s),stamp=EE.now();x.indicators ||= [];x.diagnosisFindings ||= [];x.evidenceRecords ||= [];x.surveyPriorities ||= [];
 eeSyncSelectedIndicators(x,s);
 for(const m of a.metrics){const sourceKey=`ee:${s.id}:${m.key}`;const ind=x.indicators.find(i=>i.sourceKey===sourceKey);
  let finding=x.diagnosisFindings.find(f=>f.sourceKey===sourceKey);if(!finding){finding={id:EE.uid(),sourceKey,surveyId:s.id,evidenceType:'Cuantitativa',role:'Observación',categories:[],behaviors:[],factors:[],createdAt:stamp,source:`Encuesta · ${s.title}`};x.diagnosisFindings.push(finding);}finding.text=`${m.label}: ${m.value??'Sin datos'} ${m.unit}; n=${m.n}. Resultado descriptivo de ${s.title}, versión ${s.version}.`;finding.indicator=ind?.name||'';finding.updatedAt=stamp;
 }
 for(const t of a.texts){const sourceKey=`ee:${s.id}:text:${t.responseId}:${t.question}`;if(!x.diagnosisFindings.some(f=>f.sourceKey===sourceKey))x.diagnosisFindings.push({id:EE.uid(),sourceKey,surveyId:s.id,text:t.text,evidenceType:'Cualitativa',role:'Sin determinar',source:`Encuesta · ${s.title} · ${t.question}`,categories:[],behaviors:[],factors:[],createdAt:t.date,wave:t.wave,audienceId:t.audienceId});}
 const key='ee:'+s.id;let ev=x.evidenceRecords.find(e=>e.sourceKey===key);const record={sourceKey:key,source:'Encuestas y experiencias',surveyId:s.id,type:'survey',variable:s.title,kind:'declarado',date:stamp.slice(0,10),value:a.metrics.map(m=>m.label+': '+(m.value??'Sin datos')+' '+m.unit+' (n='+m.n+')').join('; '),title:s.title,sampleSize:a.n,metrics:a.metrics,updatedAt:stamp};if(ev)Object.assign(ev,record);else x.evidenceRecords.push({id:EE.uid(),...record});
 const signals=a.metrics.filter(m=>m.value!==null&&(m.unit==='puntos'?m.value<0:m.direction==='lower'?m.value>=60:m.value<40)).map(m=>({sourceKey:`${key}:${m.key}`,surveyId:s.id,label:m.label,value:m.value,n:m.n,reason:m.direction==='lower'?'Desgaste elevado':m.unit==='puntos'?'Balance negativo':'Nivel descriptivo bajo',status:'Revisar con evidencia'}));x.surveyPriorities=x.surveyPriorities.filter(p=>p.surveyId!==s.id).concat(signals);
 x.changeCapacityInputs=EE.simulation(x);s.syncedAt=stamp;
}
function eeResults(x,s){if(!eeFilter.wave)return eeEvolutionResults(x,s);const a=EE.summarize(s,eeFilter),waves=[...new Set(s.responses.map(r=>r.wave))];return `<section class="panel"><div class="flex" style="justify-content:space-between"><h3>Resultados · ${a.n} respuestas</h3><div class="flex"><button class="secondary" onclick="eeExportResponses()">↓ Respuestas CSV</button><button class="secondary" onclick="eeExportSummary()">↓ Resultados JSON</button></div></div><div class="grid"><label>Momento / categoría<select onchange="eeFilter.wave=this.value;render()"><option value="">Todos los momentos / categorías</option>${eeOptions(waves,eeFilter.wave)}</select></label><label>Audiencia<select onchange="eeFilter.audienceId=this.value;render()">${eeAudienceOptions(x,eeFilter.audienceId)}</select></label></div>${eeDetailedPanel(x,s)}<details><summary>Resumen original del instrumento y comparación temporal</summary><div class="ee-metrics">${a.metrics.map(m=>`<article class="ee-metric"><span>${safe(m.label)}</span><strong>${m.value??'—'}<small>${m.unit}</small></strong><small>n = ${m.n} · ${m.direction==='lower'?'Mayor = más desgaste':'Mayor = más favorable'}</small>${m.unit==='puntos'?`<small>Promotores ${m.promoters} · Pasivos ${m.passives} · Detractores ${m.detractors}</small>`:`<div class="bar"><span style="width:${m.value??0}%;${m.direction==='lower'?'background:#efac73':''}"></span></div>`}</article>`).join('')||'<p>Esta encuesta recoge experiencias cualitativas.</p>'}</div></details>${eeDistributionSelector(s)}<details><summary>Cómo calculamos los resultados</summary><p class="muted">No se imputan respuestas faltantes. En los niveles nuevos cada participante tiene igual peso. El resumen original conserva su cálculo por ítem respondido, por compatibilidad con mediciones previas. Conocimiento = porcentaje de aciertos. NPS/CNPS: 9–10 promotores, 7–8 pasivos, 0–6 detractores; rango −100 a 100.</p></details><div class="flex"><button class="secondary" onclick="go('Diagnóstico')">Ver Diagnóstico</button><button class="secondary" onclick="go('Indicadores')">Ver Indicadores</button><button class="secondary" onclick="eeExportSimulation()">↓ Entradas para simulación</button></div></section>`;}
function eeFilteredResponses(s){return s.responses.filter(r=>(!eeFilter.wave||r.wave===eeFilter.wave)&&(!eeFilter.audienceId||r.audienceId===eeFilter.audienceId));}
function eeExportResponses(){const s=eeSurvey(),keys=['response_id','fecha','codigo','audiencia_id','ola','importado_el','lote_importacion',...s.questions.map(q=>q.id)];eeDownload('respuestas-'+s.id+'.csv',EE.csv([keys,...eeFilteredResponses(s).map(r=>[r.id,r.date,r.respondent,r.audienceId,r.wave,r.importedAt||'',r.importBatchId||'',...s.questions.map(q=>r.answers[q.id]??'')])]),'text/csv;charset=utf-8');}
function eeExportSummary(){const s=eeSurvey();eeDownload('resultados-'+s.id+'.json',JSON.stringify({initiativeId:current().id,surveyId:s.id,version:s.version,filters:eeFilter,readingScale:eeBalanceRanges(),evolution:EE.evolution(s,eeFilter.audienceId),importHistory:s.importHistory||[],...EE.summarize(s,eeFilter),detailed:EE.detailed(s,eeFilter),composition:EE.composition(s,eeFilter)},null,2),'application/json');}
function eeExportSimulation(){eeDownload('capacidad-cambio-entradas.json',JSON.stringify(EE.simulation(current()),null,2),'application/json');}
function eeImportPanel(s){return `<section class="panel"><h3>Importar respuestas de Excel / CSV</h3><label>Momento / categoría de esta carga<input id="ee-import-moment" list="ee-import-moments" value="${safe(s.wave||'Antes')}" placeholder="Ej. Diagnóstico inicial o resultado final"></label><datalist id="ee-import-moments"><option value="Antes"><option value="Durante"><option value="Después"></datalist><p class="muted">Se usa si el Excel no trae Momento / ola. La fecha y hora de importación se registran al confirmar.</p>${s.status==='draft'?'<p class="notice">¿La encuesta ya está en tu Excel? Carga el archivo aquí para crear un instrumento nuevo con todas las preguntas y respuestas.</p><input type="file" accept=".xlsx,.csv" onchange="eeQuickRead(this)">':''}<p class="muted">XLSX: primera hoja, encabezados en la primera fila. CSV: UTF-8, coma, punto y coma o tabulación. Máximo 10 MB y 10.000 filas. Guarda fechas como texto ISO. No admite .xls antiguo.</p><button class="secondary" onclick="eeTemplateCSV()">↓ Plantilla CSV para Excel</button><label>Archivo<input type="file" accept=".xlsx,.csv" onchange="eeReadImport(this)"></label><div id="ee-import-content"></div></section>`;}
function eeTemplateCSV(){const s=eeSurvey();eeDownload('plantilla-'+s.id+'.csv',EE.csv([['response_id','fecha','codigo','audiencia_id','ola',...s.questions.map(q=>q.id)],['','','',s.audienceId,s.wave,...s.questions.map(()=> '')]]),'text/csv;charset=utf-8');}
async function eeReadImport(input){const file=input.files?.[0],s=eeSurvey(),id=s.id,initiativeId=current().id,importMoment=document.getElementById('ee-import-moment')?.value.trim()||s.wave||'Antes';eeImport=null;if(!file)return;try{if(s.status!=='active')throw Error('Activa la encuesta antes de importar.');if(file.size>10*1024*1024)throw Error('Máximo 10 MB.');const data=/\.xlsx$/i.test(file.name)?await eeReadXLSX(file):EE.records(EE.parseCSV(await file.text()));if(current()?.id!==initiativeId||eeSurvey()?.id!==id)return;if(data.rows.length>10000)throw Error('Máximo 10000 filas.');eeImport={...data,surveyId:id,initiativeId,accepted:null,importMoment,fileName:file.name};const fields=[['response_id','ID externo (recomendado)'],['fecha','Fecha ISO (opcional)'],['codigo','Código (opcional)'],['audiencia_id','ID audiencia (opcional)'],['ola','Ola (opcional)'],...s.questions.map(q=>[q.id,q.label])];$('ee-import-content').innerHTML=`<h3>Relacionar columnas · ${data.rows.length} filas</h3><p class="muted">IDs estables permiten detectar repetidos. Sin ID, se compara el contenido de la fila.</p>${fields.map(([key,label])=>{const match=data.headers.includes(key)?key:data.headers.includes(label)?label:'';return `<label>${safe(label)}<select data-ee-map="${safe(key)}"><option value="">Sin columna</option>${eeOptions(data.headers,match)}</select></label>`;}).join('')}<button class="primary" onclick="eePreviewImport()">Validar y ver vista previa</button><div id="ee-preview"></div>`;}catch(e){eeMsg(e.message,true);}}
async function eeDigest(text){const buffer=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return [...new Uint8Array(buffer)].map(b=>b.toString(16).padStart(2,'0')).join('');}
async function eePreviewImport(){const state=eeImport,s=eeSurvey(),x=current();if(!state||state.surveyId!==s.id)return;try{const mapping=Object.fromEntries([...document.querySelectorAll('[data-ee-map]')].map(el=>[el.dataset.eeMap,el.value]));const cols=Object.values(mapping).filter(Boolean);if(new Set(cols).size!==cols.length)throw Error('Una columna no puede usarse para dos campos.');for(const q of s.questions)if(q.required&&!mapping[q.id])throw Error('Falta columna obligatoria: '+q.label);const seen=new Set(s.responses.flatMap(r=>[r.id,r.externalId,r.importKey].filter(Boolean))),accepted=[],errors=[];let duplicates=0;
 for(let i=0;i<state.rows.length;i++){const row=state.rows[i],get=k=>mapping[k]?row[mapping[k]]?.trim()||'':'',v=EE.validateResponse(s,Object.fromEntries(s.questions.map(q=>[q.id,get(q.id)])));let audienceId=get('audiencia_id')||s.audienceId,wave=get('ola')||state.importMoment||s.wave,date=get('fecha'),externalId=get('response_id');
  if(audienceId&&!(x.audiences||[]).some(a=>String(a.id)===audienceId))v.errors.push('Audiencia desconocida: '+audienceId);
  if(date&&(!/^\d{4}-\d{2}-\d{2}(T.*)?$/.test(date)||!Number.isFinite(Date.parse(date))))v.errors.push('Fecha inválida; usa ISO (AAAA-MM-DD)');
  if(v.errors.length){errors.push({row:i+2,message:v.errors.join('; ')});continue;}
  const importKey=externalId||'sha256:'+await eeDigest(JSON.stringify([get('codigo'),audienceId,wave,date,v.answers]));if(seen.has(importKey)){duplicates++;continue;}seen.add(importKey);accepted.push({id:externalId||EE.uid(),externalId,importKey,date:date||EE.now(),respondent:get('codigo'),audienceId,wave,answers:v.answers,source:'import'});
 }
 if(eeImport!==state||eeSurvey()?.id!==s.id||current()?.id!==x.id)return;state.accepted=accepted;state.errors=errors;$('ee-preview').innerHTML=`<p>${accepted.length} válidas · ${duplicates} repetidas · ${errors.length} con errores</p>${errors.slice(0,30).map(er=>`<p class="notice">Fila ${er.row}: ${safe(er.message)}</p>`).join('')}<div style="overflow:auto"><table><tr><th>Ola</th><th>Audiencia</th><th>Respuestas (primeras 5 filas)</th></tr>${accepted.slice(0,5).map(r=>`<tr><td>${safe(r.wave)}</td><td>${safe(r.audienceId)}</td><td>${safe(JSON.stringify(r.answers))}</td></tr>`).join('')}</table></div><button class="primary" ${!accepted.length||errors.length?'disabled':''} onclick="eeCommitImport()">Confirmar importación</button><p class="muted">Si hay errores, corrige el archivo y vuelve a cargarlo. La validación no guarda datos.</p>`;
 }catch(e){eeMsg(e.message,true);}}
function eeCommitImport(){const s=eeSurvey();if(!eeImport?.accepted||eeImport.errors.length||eeImport.surveyId!==s.id||eeImport.initiativeId!==current().id||s.status!=='active')return;const seen=new Set(s.responses.flatMap(r=>[r.id,r.externalId,r.importKey].filter(Boolean)));const rows=eeImport.accepted.filter(r=>!seen.has(r.importKey)&&!seen.has(r.id));eeStampImport(s,rows,eeImport.fileName||'',eeImport.importMoment||s.wave);s.responses.push(...rows);eeIntegrate(current(),s);eeImport=null;save();eeTab='resultados';render();eeMsg(rows.length+' respuestas importadas.');}
function eeSummaryPanel(x){const list=EE.init(x).filter(s=>s.responses.length);if(!list.length)return '';return `<section class="panel"><div class="flex" style="justify-content:space-between"><h2>Evidencia de encuestas y experiencias</h2><button class="secondary" onclick="go('Encuestas y experiencias')">Abrir módulo →</button></div>${list.map(s=>{const a=EE.summarize(s);return `<p><b>${safe(s.title)}</b> · ${a.n} respuestas · ${a.metrics.map(m=>safe(m.label)+': '+(m.value??'—')+safe(m.unit)).join(' · ')}</p>`;}).join('')}${(x.surveyPriorities||[]).length?`<h3>Señales para priorizar</h3>${x.surveyPriorities.map(p=>`<p>${safe(p.label)}: ${p.value} · ${safe(p.reason)} · n=${p.n}</p>`).join('')}<p class="muted">Señales descriptivas; conservan la priorización manual de impacto y esfuerzo.</p>`:''}<button class="secondary" onclick="eeExportSimulation()">↓ Entradas para Simulación de Capacidad de Cambio</button></section>`;}
function eeSharePanel(s){return `<section class="panel"><h3>Compartir con participantes</h3><p class="muted">La captura interna e importación ya usan la persistencia existente. Para enlaces externos ejecuta una sola vez <code>supabase/encuestas_v24.sql</code>. El enlace permite responder únicamente a este instrumento.</p><div class="flex"><button class="primary" ${s.status!=='active'?'disabled':''} onclick="eePublish()">${s.publication?'Mostrar enlace':'Crear enlace de respuesta'}</button><button class="secondary" ${!s.publication?'disabled':''} onclick="eePull()">Recuperar respuestas externas</button>${s.publication?'<button class="secondary" onclick="eeRevoke()">Revocar enlace</button>':''}</div><div id="ee-public-link"></div><p class="notice">Las respuestas externas se guardan en Supabase. Se incorporan al abrir Resultados y al pulsar Recuperar. Mantén este enlace dentro de la población convocada; quien lo tenga puede responder. No se considera autenticación individual ni garantiza una respuesta por persona.</p></section>`;}
function eePublicSnapshot(s){return {id:s.id,title:s.title,kind:s.kind,version:s.version,description:s.description,wave:s.wave,audienceId:s.audienceId,instrumentNote:s.instrumentNote,questions:s.questions.map(q=>{const z={...q};delete z.correct;return z;})};}
async function eePublish(){const s=eeSurvey(),x=current();if(s.status!=='active')return;try{if(!x._cloudId||!cloudOrgId)throw Error('Espera a que la iniciativa se guarde en Supabase.');if(!s.publication){eeMsg('Creando enlace…');const {data,error}=await sb.from('ee_publications').insert({initiative_id:x._cloudId,organization_id:cloudOrgId,survey_local_id:s.id,snapshot:eePublicSnapshot(s),active:true}).select('id,token').single();if(error)throw error;s.publication=data;save();}
 if(s.publication.revoked){const {error}=await sb.from('ee_publications').update({active:true}).eq('id',s.publication.id);if(error)throw error;s.publication.revoked=false;save();}
 const url=new URL('responder.html',location.href);url.searchParams.set('t',s.publication.token);$('ee-public-link').innerHTML=`<label>Enlace de respuesta<input id="ee-link-value" readonly value="${safe(url.href)}"></label><button class="secondary" onclick="eeCopyLink()">Copiar enlace</button><a class="secondary" href="${safe(url.href)}" target="_blank" rel="noopener">Abrir formulario ↗</a>`;
 }catch(e){eeMsg('No se pudo publicar: '+e.message+'. Verifica la instalación SQL V2.4.',true);}}
async function eeCopyLink(){try{await navigator.clipboard.writeText($('ee-link-value').value);eeMsg('Enlace copiado.');}catch{$('ee-link-value').select();eeMsg('Selecciona y copia el enlace.');}}
async function eeRevoke(){const s=eeSurvey();if(!s.publication)return;try{const token=EE.uid();const {error}=await sb.from('ee_publications').update({active:false,token}).eq('id',s.publication.id);if(error)throw error;s.publication.token=token;s.publication.revoked=true;save();render();eeMsg('Enlace revocado. Todas las respuestas se conservan y pueden recuperarse.');}catch(e){eeMsg(e.message,true);}}
let eePulling=false;
async function eePull(quiet=false){const s=eeSurvey(),x=current();if(!s?.publication||eePulling)return;eePulling=true;try{const seen=new Set(s.responses.map(r=>r.id)),rows=[];let start=0;while(true){const {data,error}=await sb.from('ee_submissions').select('id,answers,respondent,created_at').eq('publication_id',s.publication.id).order('created_at').order('id').range(start,start+499);if(error)throw error;rows.push(...data);if(data.length<500)break;start+=500;if(start>=100000)throw Error('Más de 100000 respuestas: exporta desde Supabase por lotes.');}
 if(!EE.init(x).some(z=>z.id===s.id))return;let added=0,rejected=0;for(const r of rows){if(seen.has(r.id))continue;const v=EE.validateResponse(s,r.answers);if(v.errors.length){rejected++;continue;}s.responses.push({id:r.id,date:r.created_at,respondent:r.respondent||'',audienceId:s.audienceId,wave:s.wave,answers:v.answers,source:'public'});seen.add(r.id);added++;}
 if(added){eeIntegrate(x,s);save();}if(current()?.id===x.id&&eeSurvey()?.id===s.id&&(!quiet||added||rejected)){render();if(!quiet||added||rejected)eeMsg(`${added} respuestas nuevas · ${rejected} inválidas. ${quiet?'Actualización automática.':''}`);}
 }catch(e){if(!quiet)eeMsg('No se pudieron recuperar respuestas: '+e.message,true);}finally{eePulling=false;}}

function eeWaveComparison(s){
 const waves=[...new Set(s.responses.map(r=>r.wave))];if(waves.length<2)return '';
 const list=waves.map(wave=>({wave,result:EE.summarize(s,{wave,audienceId:eeFilter.audienceId})}));const keys=[...new Set(list.flatMap(z=>z.result.metrics.map(m=>m.key)))];
 return `<h3>Comparación entre olas</h3><p class="muted">Orden de primera captura. La diferencia usa la primera y última ola; no representa cambio causal ni comparación pareada de personas.</p><div style="overflow:auto"><table><tr><th>Índice</th>${list.map(z=>`<th>${safe(z.wave)}</th>`).join('')}<th>Diferencia (puntos)</th></tr>${keys.map(key=>{const first=list[0].result.metrics.find(m=>m.key===key),last=list.at(-1).result.metrics.find(m=>m.key===key);return `<tr><td>${safe(first?.label||key)}</td>${list.map(z=>{const m=z.result.metrics.find(m=>m.key===key);return `<td>${m?.value??'—'} (n=${m?.n??0})</td>`;}).join('')}<td>${first?.value!=null&&last?.value!=null?Math.round((last.value-first.value)*100)/100:'—'}</td></tr>`;}).join('')}</table></div>`;
}

function eeAllDetailedMetrics(s){const d=EE.detailed(s);const c=EE.composition(s);return [...d.questions.filter(q=>q.unit),...d.dimensions,...d.overall,...[...c.questions,...c.dimensions,c.global,c.npsReference,c.instrumentGlobal].map(m=>({key:m.key,label:'Balance tipo NPS · '+m.label,value:m.balance,n:m.n,unit:'puntos',direction:'higher',min:-100,max:100}))];}
function eeDetailedPanel(x,s){const d=EE.detailed(s,eeFilter);const cards=arr=>arr.map(m=>`<article class="ee-metric"><span>${safe(m.label)}</span><strong class="${eeTone(m.value,m).cls}">${m.value??'—'}<small>${safe(eeUnitLabel(m.unit))}</small></strong><small>n = ${m.n}${m.questionCount?' · '+m.questionCount+' preguntas':''}</small></article>`).join('')||'<p class="muted">No hay preguntas cuantitativas compatibles.</p>';return `${eeCompositionPanel(x,s)}<h3>Resultados por dimensión</h3><div class="ee-metrics">${cards(d.dimensions)}</div>${eeCommentsDashboard(s)}${eeQuestionResultsSelector(s)}<details><summary>Cómo calculamos los promedios</summary><p class="muted">${safe(d.method)}</p></details><button class="secondary" onclick="eeExportDetailedCSV()">↓ Resultados por niveles CSV</button><details><summary>Elegir resultados para Indicadores</summary><p class="muted">Elige solo los resultados que deseas seguir. Cada indicador recibe una sola fuente de esta encuesta. Sus metas y asociaciones con comportamientos se conservan. Los indicadores creados en versiones anteriores se conservan sin actualización automática hasta que los vincules aquí.</p><form onsubmit="eeSaveMetricLinks(event)">${eeAllDetailedMetrics(s).map((m,i)=>`<label>${safe(m.label)} · ${safe(eeUnitLabel(m.unit))}<select name="link_${i}"><option value="">Solo en Encuestas</option><option value="__new__">Crear indicador para este resultado</option>${x.indicators.map((r,j)=>`<option value="${j}"${s.metricLinks?.[m.key]===r.id?' selected':''}>${safe(r.name)}${r.unit?' ('+safe(r.unit)+')':''}</option>`).join('')}</select></label>`).join('')}<button class="primary">Guardar vínculos</button></form></details>`;}
function eeSyncSelectedIndicators(x,s){for(const m of eeAllDetailedMetrics(s)){const id=s.metricLinks?.[m.key];if(!id)continue;const ind=x.indicators.find(i=>i.id===id);if(!ind)continue;const signature=JSON.stringify([s.version,m.value,m.n,s.responses.length,m.key.startsWith('balance-')?s.compositionConfig||{}:null]);if(ind.eeLinkSignature!==signature){if(m.value!==null){ind.history ||= [];ind.history.push({date:EE.now(),value:m.value,n:m.n,surveyId:s.id,metricKey:m.key,compositionConfig:m.key.startsWith('balance-')?structuredClone(s.compositionConfig||{}):null});}Object.assign(ind,{value:m.value,n:m.n,unit:m.unit,eeLinkSignature:signature,eeMetricKey:m.key,eeSurveyId:s.id});}}}
function eeSaveMetricLinks(e){e.preventDefault();const x=current(),s=eeSurvey(),fd=new FormData(e.target),metrics=eeAllDetailedMetrics(s),entries=metrics.map((m,i)=>({m,value:fd.get('link_'+i)||''})),used=new Set();for(const {m,value} of entries){if(!value||value==='__new__')continue;const ind=x.indicators[Number(value)];if(!ind)return eeMsg('Indicador no disponible',true);if(used.has(value))return eeMsg('Selecciona un indicador diferente para cada resultado.',true);used.add(value);if(ind.unit&&ind.unit!==m.unit)return eeMsg('La unidad de '+ind.name+' no coincide con '+m.unit,true);if(EE.init(x).some(other=>other.id!==s.id&&Object.values(other.metricLinks||{}).includes(ind.id)))return eeMsg('Ese indicador ya recibe resultados de otra encuesta.',true);}
 const old=s.metricLinks||{},links={};for(const {m,value} of entries){if(!value)continue;let ind;if(value==='__new__'){ind={id:EE.uid(),name:s.title+' · '+m.label,type:'Resultados',definition:'Resultado de encuesta · '+m.label,baseline:m.value,target:'',history:[],unit:m.unit};x.indicators.push(ind);}else{ind=x.indicators[Number(value)];ind.id ||= EE.uid();}if(old[m.key]!==ind.id||ind.eeMetricKey!==m.key)delete ind.eeLinkSignature;links[m.key]=ind.id;}s.metricLinks=links;eeSyncSelectedIndicators(x,s);save();render();eeMsg('Vínculos guardados. Los demás resultados permanecen en Encuestas.');}
function eeExportDetailedCSV(){const s=eeSurvey(),d=EE.detailed(s,eeFilter);eeDownload('resultados-niveles-'+s.id+'.csv',EE.csv([['nivel','resultado','n','valor','unidad','promedio_original','ola','audiencia'],...['questions','dimensions','overall'].flatMap(level=>d[level].map(m=>[level,m.label,m.n,m.value??'',m.unit,m.mean??'',eeFilter.wave,eeFilter.audienceId]))]),'text/csv;charset=utf-8');}

async function eeQuickRead(input){const file=input.files?.[0];if(!file)return;const initiativeId=current().id;try{if(file.size>10*1024*1024)throw Error('Máximo 10 MB.');const data=/\.xlsx$/i.test(file.name)?await eeReadXLSX(file):EE.records(EE.parseCSV(await file.text()));if(current()?.id!==initiativeId)return;if(!data.rows.length||data.rows.length>10000)throw Error('El archivo debe tener entre 1 y 10000 respuestas.');eePickerOpen=false;eeQuickState={initiativeId,title:file.name.replace(/\.(xlsx|csv)$/i,''),fileName:file.name,data,columns:eeSuggestColumns(data)};render();document.getElementById('ee-quick-panel')?.scrollIntoView({block:'start'});}catch(e){eeMsg(e.message,true);}}
function eeSuggestColumns(data){return data.headers.map((header,i)=>{const key=header.normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase(),values=data.rows.map(r=>String(r[header]??'').trim()).filter(Boolean),nums=values.map(v=>Number(v.replace(',','.'))),numeric=values.length&&nums.every(Number.isFinite);let role='question';if(/^(nombre|nombres|apellido|apellidos|correo|email|documento|cedula|telefono|hora de inicio|hora de finalizacion)$/.test(key))role='ignore';if(/^(response_id|id respuesta|id)$/.test(key))role='response_id';if(/^(codigo|codigo participante|alias)$/.test(key))role='codigo';if(/^(fecha|fecha respuesta)$/.test(key))role='fecha';if(/^(audiencia_id|audiencia)$/.test(key))role='audiencia_id';if(/^(ola|momento)$/.test(key))role='ola';const min=numeric?Math.min(...nums):0,max=numeric?Math.max(...nums):0,scaleMin=min>=1&&max<=5?1:0,scaleMax=max<=5&&min>=1?5:max<=10?10:Math.max(max,1);let type=numeric?'scale':'text';if(numeric&&min>=0&&max<=10&&nums.every(Number.isInteger)&&/nps|recomendar/.test(key))type=/cnps/.test(key)?'cnps':'nps';return {header,role,type,min:scaleMin,max:scaleMax,dimension:'',reverse:false,sample:values.slice(0,2).join(' / '),id:'q_'+String(i+1).padStart(3,'0')};});}
function eeQuickPanel(){const st=eeQuickState;if(st.initiativeId!==current().id){eeQuickState=null;return '';}return `<section id="ee-quick-panel" class="panel"><h2>Crear encuesta e importar desde Excel</h2><p>${st.data.rows.length} filas · ${st.columns.length} columnas. Revisa las propuestas en esta tabla; las preguntas se crearán automáticamente.</p><p class="notice">Las escalas propuestas se basan en los valores observados: confirma sus límites reales. NPS/CNPS solo corresponden a preguntas 0–10 con ese propósito. Puedes excluir columnas personales o administrativas.</p><form onsubmit="eeQuickConfirm(event)"><label>Nombre del instrumento<input name="title" required value="${safe(st.title)}"></label><label>Momento / categoría de medición<input name="wave" required value="Antes" list="ee-moment-options" placeholder="Ej. Diagnóstico inicial, después de formación, resultado final"></label><datalist id="ee-moment-options"><option value="Antes"><option value="Durante"><option value="Después"></datalist><p class="muted">Si asignas una columna como Momento / ola, sus valores se conservarán; este momento se usa donde falten.</p><label>Audiencia por defecto<select name="audienceId">${eeAudienceOptions(current(),'')}</select></label><div class="flex"><label>Tipo para todas las preguntas<select id="ee-quick-bulk-type">${eeOptions(['scale','nps','cnps','text'],'scale')}</select></label><label>Mínimo<input id="ee-quick-bulk-min" type="number" step="any" value="0"></label><label>Máximo<input id="ee-quick-bulk-max" type="number" step="any" value="10"></label><button type="button" class="secondary" onclick="eeQuickBulk()">Aplicar a preguntas</button></div><div style="overflow:auto"><table><thead><tr><th>Columna / pregunta</th><th>Usar como</th><th>Tipo</th><th>Mín.</th><th>Máx.</th><th>Dimensión</th><th>Invertir</th><th>Ejemplo</th></tr></thead><tbody>${st.columns.map((col,i)=>`<tr data-quick-col="${i}"><td>${safe(col.header)}</td><td><select data-q="role">${[['question','Pregunta'],['ignore','Excluir columna'],['response_id','ID de respuesta'],['codigo','Código participante'],['fecha','Fecha'],['audiencia_id','ID de audiencia'],['ola','Momento / ola']].map(([v,label])=>`<option value="${v}"${col.role===v?' selected':''}>${label}</option>`).join('')}</select></td><td><select data-q="type">${eeOptions(['scale','nps','cnps','text'],col.type)}</select></td><td><input style="width:75px" data-q="min" type="number" step="any" value="${col.min}"></td><td><input style="width:75px" data-q="max" type="number" step="any" value="${col.max}"></td><td><input data-q="dimension" placeholder="Opcional"></td><td><input data-q="reverse" type="checkbox" style="width:auto"></td><td>${safe(col.sample)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Las audiencias de una columna deben usar los IDs registrados en HACERLO. Fechas: AAAA-MM-DD. Se creará un instrumento nuevo; los existentes se conservan.</p><button class="primary">Crear encuesta e importar respuestas</button><button class="secondary" type="button" onclick="eeQuickState=null;eePickerOpen=true;render()">Cancelar</button></form><p id="ee-quick-error" role="alert"></p></section>`;}
function eeQuickBulk(){const root=document.getElementById('ee-quick-panel');root.querySelectorAll('[data-quick-col]').forEach(row=>{if(row.querySelector('[data-q="role"]').value!=='question')return;for(const k of ['type','min','max'])row.querySelector('[data-q="'+k+'"]').value=document.getElementById('ee-quick-bulk-'+k).value;});}
async function eeQuickConfirm(e){e.preventDefault();const st=eeQuickState,x=current();if(!st||st.initiativeId!==x.id||st.busy)return;st.busy=true;const button=e.target.querySelector('button.primary');button.disabled=true;try{const fd=new FormData(e.target),columns=[...e.target.querySelectorAll('[data-quick-col]')].map(row=>{const original=st.columns[Number(row.dataset.quickCol)],get=k=>row.querySelector('[data-q="'+k+'"]');return {...original,role:get('role').value,type:get('type').value,min:Number(get('min').value),max:Number(get('max').value),dimension:get('dimension').value.trim(),reverse:get('reverse').checked};});const metadata=columns.filter(c=>!['question','ignore'].includes(c.role));if(new Set(metadata.map(c=>c.role)).size!==metadata.length)throw Error('Cada campo administrativo debe asignarse a una sola columna.');const questions=columns.filter(c=>c.role==='question').map(c=>{const q={id:c.id,label:c.header,type:c.type,dimension:c.dimension,required:false};if(c.type!=='text'){q.min=c.type==='scale'?c.min:0;q.max=c.type==='scale'?c.max:10;}if(c.reverse){if(c.type!=='scale')throw Error('Invertir solo aplica a scale.');q.reverse=true;}return q;});EE.validateQuestions(questions);const survey=EE.create('Libre',String(fd.get('title')||'').trim());if(!survey.title)throw Error('Indica el nombre.');Object.assign(survey,{questions,wave:String(fd.get('wave')||'Base'),audienceId:fd.get('audienceId')||'',status:'active'});const accepted=[],seen=new Set();let duplicates=0;for(let i=0;i<st.data.rows.length;i++){const row=st.data.rows[i],get=role=>String(row[metadata.find(c=>c.role===role)?.header]??'').trim(),v=EE.validateResponse(survey,Object.fromEntries(columns.filter(c=>c.role==='question').map(c=>[c.id,row[c.header]])));if(v.errors.length)throw Error('Fila '+(i+2)+': '+v.errors.join('; '));if(!Object.keys(v.answers).length)continue;const audienceId=get('audiencia_id')||survey.audienceId,date=get('fecha'),wave=get('ola')||survey.wave,externalId=get('response_id');if(audienceId&&!x.audiences.some(a=>String(a.id)===audienceId))throw Error('Fila '+(i+2)+': audiencia desconocida; usa su ID o excluye esa columna.');if(date&&(!/^\d{4}-\d{2}-\d{2}(T.*)?$/.test(date)||!Number.isFinite(Date.parse(date))))throw Error('Fila '+(i+2)+': fecha inválida; usa AAAA-MM-DD o excluye esa columna.');const importKey=externalId||'sha256:'+await eeDigest(JSON.stringify([i,get('codigo'),audienceId,wave,date,v.answers]));if(seen.has(importKey)){duplicates++;continue;}seen.add(importKey);accepted.push({id:externalId||EE.uid(),externalId,importKey,date:date||EE.now(),respondent:get('codigo'),audienceId,wave,answers:v.answers,source:'import'});}if(!accepted.length)throw Error('No hay respuestas válidas.');if(current()?.id!==st.initiativeId||eeQuickState!==st)return;eeStampImport(survey,accepted,st.fileName||st.title,survey.wave);survey.responses=accepted;EE.init(x).push(survey);eeIntegrate(x,survey);eeSelected=survey.id;eeQuickState=null;eeTab='resultados';eeFilter={wave:'',audienceId:''};save();render();eeMsg(accepted.length+' respuestas importadas. '+duplicates+' repetidas omitidas.');}catch(err){document.getElementById('ee-quick-error').textContent=err.message;}finally{st.busy=false;if(button.isConnected)button.disabled=false;}}

function eeCompositionPanel(x,s){const c=EE.composition(s,eeFilter),g=c.global,fmt=v=>v===null?'—':Number(v).toLocaleString('es-CO',{maximumFractionDigits:2}),signed=v=>v===null?'—':(v>0?'+':'')+fmt(v),pct=v=>v===null?'—':fmt(v)+'%',cell=(n,p)=>`${n} <small>(${pct(p)})</small>`,row=q=>`<tr><td>${safe(q.label)}${q.reverse?'<br><small>Sentido invertido</small>':''}</td><td>${q.n}</td><td>${fmt(q.mean)}</td><td>${cell(q.promoters,q.promotersPercent)}</td><td>${cell(q.passives,q.passivesPercent)}</td><td>${cell(q.detractors,q.detractorsPercent)}</td><td class="${eeTone(q.balance,{unit:'puntos'}).cls}">${signed(q.balance)}</td></tr>`,table=rows=>`<div style="overflow:auto"><table class="ee-composition-table"><thead><tr><th>Pregunta / componente</th><th>Base válida</th><th>Promedio</th><th>Promotores ≥9</th><th>Pasivos 7–&lt;9</th><th>Detractores &lt;7</th><th>Balance tipo NPS</th></tr></thead><tbody>${rows.map(row).join('')}</tbody></table></div>`;
 return `<section class="panel"><h2>Tu resultado</h2>${eeColorGuide()}<details><summary>Cómo leer estos resultados</summary><p class="muted">${c.mode==='original'?'Puntuaciones originales de escalas 0–10 o 1–10.':'Escalas convertidas linealmente a 0–10; el mínimo equivale a 0 y el máximo a 10.'} ${c.totalRows} filas en el filtro. Los balances de satisfacción u otros componentes son medidas descriptivas tipo NPS; NPS de recomendación corresponde a su pregunta específica.</p></details><details><summary>Configurar composición global y escalas</summary><form onsubmit="eeSaveComposition(event)"><label>Tratamiento de escala<select name="mode"><option value="original"${c.mode==='original'?' selected':''}>Original: solo 0–10 y 1–10</option><option value="normalized"${c.mode==='normalized'?' selected':''}>Normalizar escalas a 0–10</option></select></label><p class="muted">Para incluir escalas 1–5, guarda primero Normalizar y luego selecciona sus preguntas. Los resultados originales se conservan.</p><input type="hidden" name="method" value="reference"><label>Pregunta de referencia para el bloque NPS<select name="referenceId">${c.questions.map(q=>`<option value="${safe(q.questionIds[0])}"${c.referenceId===q.questionIds[0]?' selected':''}>${safe(q.label)}</option>`).join('')}</select></label><p>Preguntas que integran el global / componentes:</p>${c.questions.map(q=>`<label style="display:flex;gap:10px"><input style="width:auto" type="checkbox" name="questionIds" value="${safe(q.questionIds[0])}"${q.included?' checked':''}><span>${safe(q.label)}<input name="dimension_${safe(q.questionIds[0])}" value="${safe(s.compositionDimensions?.[q.questionIds[0]]||s.questions.find(z=>z.id===q.questionIds[0])?.dimension||'')}" placeholder="Dimensión para el NPS agrupado"></span></label>`).join('')||'<p>Sin preguntas 0–10 / 1–10; puedes habilitar la normalización.</p>'}<label style="display:flex;gap:10px"><input style="width:auto" type="checkbox" name="allowPartial"${c.allowPartial?' checked':''}> Admitir respuestas parciales en índices compuestos</label><p class="muted">Por defecto solo participan quienes respondieron todas las preguntas seleccionadas. Una pregunta complementaria puede quedar fuera del global y seguir apareciendo en la tabla.</p><button class="primary">Guardar composición</button></form></details>${c.questions.length?table(c.questions):'<p>No hay preguntas compatibles con el modo elegido.</p>'}<p><b>${c.positive} positivos · ${c.negative} negativos · ${c.neutral} neutros</b> (preguntas con balance calculable).</p>${eeCompositionCards(c,c.npsReference,'NPS','Pregunta de referencia: '+c.npsReference.label+'. Este bloque conserva el cálculo individual de esa pregunta.')}${eeCompositionCards(c,c.instrumentGlobal,'Global','Se calcula el promedio de las preguntas seleccionadas para cada participante; después se clasifica a cada persona una sola vez. El NPS consolidado es el porcentaje de promotores menos el de detractores. No se suman personas repetidas entre preguntas.')}${c.dimensions.length?'<h3>NPS global por dimensión · balance compuesto</h3><p class="muted">Se calcula un índice por participante dentro de cada dimensión y luego se clasifican sus resultados. Asigna los grupos en Configurar composición global y escalas.</p><div class="ee-metrics">'+c.dimensions.map(d=>`<article class="ee-metric"><span>${safe(d.label)}</span><strong class="${eeTone(d.balance,{unit:'puntos'}).cls}">${signed(d.balance)}<small> índice</small></strong><small>Personas que respondieron: ${d.n} · ${d.questionIds.length} preguntas</small><small>Promotores: ${d.promoters} de ${d.n} personas (${pct(d.promotersPercent)})</small><small>Pasivos: ${d.passives} de ${d.n} personas (${pct(d.passivesPercent)})</small><small>Detractores: ${d.detractors} de ${d.n} personas (${pct(d.detractorsPercent)})</small></article>`).join('')+'</div>'+table(c.dimensions):''}<button class="secondary" onclick="eeExportComposition()">↓ Composición completa CSV</button></section>`;}
function eeSaveComposition(e){e.preventDefault();const s=eeSurvey(),fd=new FormData(e.target),config={mode:fd.get('mode'),method:fd.get('method'),referenceId:fd.get('referenceId')||'',questionIds:fd.getAll('questionIds'),allowPartial:fd.get('allowPartial')==='on'};if(config.mode!==(s.compositionConfig?.mode||'original')){delete config.questionIds;}else if(!config.questionIds.length)return eeMsg('Selecciona al menos una pregunta.',true);s.compositionConfig=config;s.compositionDimensions ||= {};for(const q of s.questions){const value=fd.get('dimension_'+q.id);if(value!==null)s.compositionDimensions[q.id]=String(value).trim();}eeSyncSelectedIndicators(current(),s);save();render();eeMsg('Composición actualizada.');}
function eeExportComposition(){const s=eeSurvey(),c=EE.composition(s,eeFilter);eeDownload('composicion-'+s.id+'.csv',EE.csv([['nivel','resultado','base_valida','promedio','promotores','promotores_pct','pasivos','pasivos_pct','detractores','detractores_pct','balance','etiqueta','modo_escala','metodo_global','ola','audiencia','preguntas'],...[[...c.questions,'pregunta'],[...c.dimensions,'dimension'],[c.npsReference,'nps'],[c.instrumentGlobal,'global_instrumento']].flatMap(items=>{const level=items.pop();return items.map(q=>[level,q.label,q.n,q.mean??'',q.promoters,q.promotersPercent??'',q.passives,q.passivesPercent??'',q.detractors,q.detractorsPercent??'',q.balance??'',eeBalanceBand(q.balance).label,c.mode,c.method,eeFilter.wave,eeFilter.audienceId,q.questionIds.join('|')]);})]),'text/csv;charset=utf-8');}

function eeTrashPanel(x){const trash=x.surveyTrash||[];return trash.length?`<details><summary>Papelera · ${trash.length}</summary>${trash.map((entry,i)=>`<div class="panel"><b>${safe(entry.survey.title)}</b><p>${entry.survey.responses.length} respuestas conservadas</p><button class="secondary" onclick="eeRestoreSurvey(${i})">Restaurar</button></div>`).join('')}</details>`:'';}
async function eeRenameSurvey(e){e.preventDefault();const x=current(),s=eeSurvey();if(!s)return;const title=String(new FormData(e.target).get('title')||'').trim();if(!title||title.length>160)return eeMsg('Indica un nombre de hasta 160 caracteres.',true);try{if(s.publication){const snapshot={...eePublicSnapshot(s),title};const {error}=await sb.from('ee_publications').update({snapshot}).eq('id',s.publication.id);if(error)throw error;}if(!EE.init(x).includes(s))return;const old=s.title;s.title=title;s.updatedAt=EE.now();s.titleHistory ||= [];s.titleHistory.push({previous:old,current:title,date:s.updatedAt});for(const f of x.diagnosisFindings||[])if(f.surveyId===s.id&&f.sourceKey?.startsWith('ee:'))f.source=String(f.source||'').replace(old,title);for(const ev of x.evidenceRecords||[])if(ev.surveyId===s.id){ev.title=title;ev.variable=title;}save();render();eeMsg('Nombre actualizado; preguntas y respuestas conservadas.');}catch(err){eeMsg('No se pudo cambiar el nombre: '+err.message,true);}}
async function eeDeleteSurvey(){const x=current(),s=eeSurvey();if(!s)return;if(!confirm('¿Eliminar «'+s.title+'»? Se enviará a la papelera con sus respuestas. Si tiene enlace público se cerrará. Los indicadores se conservarán.'))return;try{if(s.publication){const token=EE.uid();const {error}=await sb.from('ee_publications').update({active:false,token}).eq('id',s.publication.id);if(error)throw error;s.publication.token=token;s.publication.revoked=true;s.status='closed';}if(!EE.init(x).includes(s))return;const bundle={survey:s,deletedAt:EE.now(),related:{}};for(const key of ['diagnosisFindings','evidenceRecords','surveyPriorities']){bundle.related[key]=(x[key]||[]).filter(r=>r.surveyId===s.id&&r.sourceKey?.startsWith('ee:'));x[key]=(x[key]||[]).filter(r=>!bundle.related[key].includes(r));}x.surveyTrash ||= [];x.surveyTrash.push(bundle);x.surveys=x.surveys.filter(z=>z.id!==s.id);x.changeCapacityInputs=EE.simulation(x);if(current()?.id===x.id){eeSelected=null;eePickerOpen=true;eeImport=null;}save();render();eeMsg('Encuesta eliminada. Puedes recuperarla desde Papelera.');}catch(err){eeMsg('No se pudo eliminar: '+err.message,true);}}
function eeRestoreSurvey(i){const x=current(),entry=x.surveyTrash?.[i];if(!entry)return;if(EE.init(x).some(s=>s.id===entry.survey.id))return eeMsg('Esta encuesta ya está activa.',true);EE.init(x).push(entry.survey);for(const key of ['diagnosisFindings','evidenceRecords','surveyPriorities']){x[key] ||= [];for(const row of entry.related[key]||[])if(!x[key].some(r=>r.sourceKey===row.sourceKey))x[key].push(row);}x.surveyTrash.splice(i,1);x.changeCapacityInputs=EE.simulation(x);eePickerOpen=false;eeSelected=entry.survey.id;eeTab='resultados';save();render();eeMsg('Encuesta restaurada. Si tenía enlace público, permanece cerrado hasta reabrirlo.');}

function eeStampImport(s,rows,fileName,moment){if(!rows.length)return;const date=EE.now(),batchId=EE.uid();for(const r of rows){r.importedAt=date;r.importBatchId=batchId;}s.lastImportedAt=date;s.importHistory ||= [];s.importHistory.push({id:batchId,importedAt:date,fileName,moment:moment||'',waves:[...new Set(rows.map(r=>r.wave))],count:rows.length});}
function eeImportHistory(s){const history=s.importHistory||[];if(!history.length)return (s.responses||[]).some(r=>r.source==='import')?'<p class="muted">Carga anterior: fecha y hora de importación no registradas.</p>':'';const fmt=value=>new Date(value).toLocaleString('es-CO',{timeZone:'America/Bogota'});return `<p class="muted">Última importación: ${safe(fmt(history.at(-1).importedAt))} · hora Colombia</p><details><summary>Momentos e historial de importación</summary><div style="overflow:auto"><table><tr><th>Momento de medición</th><th>Importado el · Colombia</th><th>Archivo</th><th>Respuestas</th></tr>${history.slice().reverse().map(batch=>`<tr><td>${batch.waves.map(safe).join(', ')}</td><td>${safe(fmt(batch.importedAt))}</td><td>${safe(batch.fileName)}</td><td>${batch.count}</td></tr>`).join('')}</table></div></details>`;}

function eeMomentEditor(s){const values=[...new Set([s.wave||'Base',...s.responses.map(r=>r.wave||'Base')])];return `<details><summary>Definir o cambiar momento / categoría</summary><p class="muted">Etiqueta esta medición para contrastarla con otras: Diagnóstico inicial, después de formación, resultado final u otra categoría propia.</p><form onsubmit="eeSaveMoment(event)"><label>Momento / categoría actual<select name="previous">${eeOptions(values,s.wave||'Base')}</select></label><label>Nuevo momento / categoría<input name="moment" required maxlength="80" placeholder="Ej. Diagnóstico inicial · octubre 2026"></label><p class="muted">Se cambiará la etiqueta de las respuestas de ese grupo. Los demás grupos se conservan. Para registrar una medición posterior, importa sus respuestas con otra etiqueta.</p><button class="primary">Guardar momento / categoría</button></form></details>`;}
async function eeSaveMoment(e){e.preventDefault();const s=eeSurvey(),x=current();if(!s)return;const fd=new FormData(e.target),previous=String(fd.get('previous')||'Base'),moment=String(fd.get('moment')||'').trim();if(!moment||moment.length>80)return eeMsg('Escribe una categoría de hasta 80 caracteres.',true);if(moment===previous)return eeMsg('La categoría ya tiene ese nombre.');try{if((s.wave||'Base')===previous&&s.publication){const snapshot={...eePublicSnapshot(s),wave:moment};const {error}=await sb.from('ee_publications').update({snapshot}).eq('id',s.publication.id);if(error)throw error;}if(!EE.init(x).includes(s))return;let count=0;for(const r of s.responses)if((r.wave||'Base')===previous){r.wave=moment;count++;}if((s.wave||'Base')===previous)s.wave=moment;if(s.baselineMoment===previous)s.baselineMoment=moment;if(s.momentSettings?.[previous]){s.momentSettings[moment]=s.momentSettings[previous];delete s.momentSettings[previous];}s.momentHistory ||= [];s.momentHistory.push({previous,current:moment,count,changedAt:EE.now()});x.changeCapacityInputs=EE.simulation(x);if(eeFilter.wave===previous)eeFilter.wave=moment;save();render();eeMsg('Momento / categoría actualizado en '+count+' respuestas.');}catch(err){eeMsg('No se pudo cambiar la categoría: '+err.message,true);}}

function eeLockedDesigner(s){return `<section class="panel"><h2>Editar preguntas</h2><p class="muted">Puedes corregir o aclarar los textos conservando sus respuestas. Si necesitas cambiar el significado, tipo o escala, utiliza Duplicar / nueva versión para mantener mediciones comparables.</p><form onsubmit="eeSaveQuestionTexts(event)">${s.questions.map((q,i)=>`<fieldset class="ee-question"><strong>Pregunta ${i+1}</strong><label>Texto de la pregunta<textarea name="question_${i}" required maxlength="2000">${safe(q.label)}</textarea></label><p class="muted">${safe(q.type)}${['scale','nps','cnps'].includes(q.type)?' · Escala '+q.min+'–'+q.max:''}${q.dimension?' · '+safe(q.dimension):''} · ID: ${safe(q.id)}</p></fieldset>`).join('')}<button class="primary">Guardar cambios de preguntas</button><button type="reset" class="secondary">Descartar cambios</button></form><details><summary>Historial de edición de preguntas</summary>${(s.questionTextHistory||[]).slice().reverse().map(entry=>`<article class="ee-question"><small>${safe(new Date(entry.changedAt).toLocaleString('es-CO',{timeZone:'America/Bogota'}))} · Colombia</small>${entry.changes.map(change=>`<p><b>${safe(change.questionId)}</b><br>Anterior: ${safe(change.previous)}<br>Actual: ${safe(change.current)}</p>`).join('')}</article>`).join('')||'<p class="muted">Sin ediciones registradas.</p>'}</details><div class="flex">${s.status==='active'?'<button class="secondary" onclick="eeStatus(&quot;closed&quot;)">Cerrar captura</button>':'<button class="secondary" onclick="eeStatus(&quot;active&quot;)">Reabrir captura</button>'}</div></section>`;}
async function eeSaveQuestionTexts(e){e.preventDefault();const x=current(),s=eeSurvey();if(!s)return;try{const fd=new FormData(e.target),changes=[],questions=s.questions.map((q,i)=>{const label=String(fd.get('question_'+i)||'').trim();if(!label||label.length>2000)throw Error('Cada pregunta requiere un texto de hasta 2000 caracteres.');if(label!==q.label)changes.push({questionId:q.id,previous:q.label,current:label});return {...q,label};});if(!changes.length)return eeMsg('No hay cambios en las preguntas.');EE.validateQuestions(questions);if(s.publication){const snapshot={...eePublicSnapshot(s),questions:questions.map(q=>{const publicQuestion={...q};delete publicQuestion.correct;return publicQuestion;})};const {error}=await sb.from('ee_publications').update({snapshot}).eq('id',s.publication.id);if(error)throw error;}if(!EE.init(x).includes(s))return;s.questions=questions;s.updatedAt=EE.now();s.questionTextHistory ||= [];s.questionTextHistory.push({changedAt:s.updatedAt,changes});save();render();eeMsg('Preguntas actualizadas. Respuestas y escalas conservadas.');}catch(err){eeMsg('No se pudieron guardar las preguntas: '+err.message,true);}}

function eeCompositionCards(c,m,title,explanation){const fmt=v=>v===null?'—':Number(v).toLocaleString('es-CO',{maximumFractionDigits:2}),signed=v=>v===null?'—':(v>0?'+':'')+fmt(v);return `<h3>${safe(title)}</h3><details><summary>Cómo se calcula</summary><p class="muted">${safe(explanation)}</p></details><div class="ee-metrics"><article class="ee-metric"><span>${title==='Global'?'NPS consolidado del instrumento':'NPS de referencia'} · índice de −100 a 100</span><strong class="${eeTone(m.balance,{unit:'puntos'}).cls}">${signed(m.balance)}<small> índice</small></strong><span class="ee-reading ${eeTone(m.balance,{unit:'puntos'}).cls}">${eeTone(m.balance,{unit:'puntos'}).label}</span><small>Personas que respondieron: ${m.n} participantes de ${c.totalRows} filas</small><small>${c.totalRows-m.n} registros sin las respuestas requeridas para este cálculo</small><small>Promedio: ${fmt(m.mean)} / 10 · ${m.questionIds.length} preguntas</small></article>${[['Promotores ≥9',m.promoters,m.promotersPercent,'ee-positive'],['Pasivos ≥7 y <9',m.passives,m.passivesPercent,''],['Detractores <7',m.detractors,m.detractorsPercent,'ee-negative']].map(([label,n,percent,cls])=>`<article class="ee-metric"><span>${safe(label)}</span><strong class="${cls}">${n}</strong><small>${n} de ${m.n} personas · ${fmt(percent)}${percent===null?'':'%'}</small></article>`).join('')}</div><details><summary>Ver cálculo y preguntas incluidas</summary><p>${m.n?`(${m.promoters} − ${m.detractors}) ÷ ${m.n} × 100 = <b>${signed(m.balance)}</b>`:'Sin base válida para calcular este resultado.'}</p>${title==='Global'?`<p class="muted">${c.allowPartial?'Se admiten respuestas parciales.':'Se incluyen solo participantes con todas las preguntas seleccionadas respondidas.'} La clasificación usa el índice sin redondearlo. El bloque NPS de referencia y este Global pueden tener bases distintas.</p>`:''}<p class="muted">Preguntas incluidas: ${m.questionIds.map(id=>safe(c.questions.find(q=>q.questionIds[0]===id)?.label||id)).join(' · ')||'Ninguna'}</p></details>`;}

let eeEvolutionMetric='evo:global';
function eeNumber(v){return v===null||v===undefined?'—':Number(v).toLocaleString('es-CO',{maximumFractionDigits:2});}
function eeChange(v){return v===null?'Sin comparación':v>0?'↑ '+eeNumber(v):v<0?'↓ '+eeNumber(Math.abs(v)):'Sin cambio';}
function eeEvolutionFilters(x,s,e){return `<div class="grid"><label>Momento<select onchange="eeFilter.wave=this.value;render()"><option value="">Todos los momentos</option>${eeOptions(e.series.map(m=>m.wave),eeFilter.wave)}</select></label><label>Audiencia<select onchange="eeFilter.audienceId=this.value;render()">${eeAudienceOptions(x,eeFilter.audienceId)}</select></label></div>`;}
function eeEvolutionChart(e,keys){const colors=['#f2ca68','#52d4c7'];const min=-100,max=100,left=54,right=700,top=25,bottom=180,x=i=>left+i*(right-left)/Math.max(1,e.series.length-1),y=v=>bottom-(v-min)*(bottom-top)/(max-min);return `<div class="ee-chart-scroll"><svg class="ee-evolution-chart" viewBox="0 0 750 250" role="img" aria-label="Evolución de NPS y Global por momento">${[-100,-50,0,50,100].map(v=>`<line x1="${left}" y1="${y(v)}" x2="${right}" y2="${y(v)}" stroke="${v===0?'#688598':'#244556'}"/><text x="44" y="${y(v)+4}" text-anchor="end" fill="#abc5d4" font-size="11">${v}</text>`).join('')}${e.series.map((m,i)=>`<text x="${x(i)}" y="205" text-anchor="${i===0?'start':i===e.series.length-1?'end':'middle'}" fill="#d9edf4" font-size="11">${safe(m.wave.slice(0,23))}</text>`).join('')}${keys.map((key,k)=>{const points=e.series.map((m,i)=>({i,m:m.metrics.find(v=>v.key===key)}));return points.map((p,i)=>{const next=points[i+1];return p.m?.value!==null&&p.m?.value!==undefined?`${next?.m?.value!==null&&next?.m?.value!==undefined?`<line x1="${x(p.i)}" y1="${y(p.m.value)}" x2="${x(next.i)}" y2="${y(next.m.value)}" stroke="${colors[k]}" stroke-width="3"/>`:''}<circle cx="${x(p.i)}" cy="${y(p.m.value)}" r="5" fill="${colors[k]}"><title>${safe(e.series[p.i].wave)} · ${safe(p.m.label)}: ${p.m.value}; ${p.m.n} personas</title></circle>`:'';}).join('');}).join('')}<text x="54" y="238" fill="${colors[0]}" font-size="12">● NPS</text><text x="160" y="238" fill="${colors[1]}" font-size="12">● Global</text></svg></div>`;}
function eeMetricChart(e,key){const metrics=e.series.map(m=>m.metrics.find(v=>v.key===key)),ref=metrics.find(Boolean);if(!ref)return '<p>Sin resultados para esta variable.</p>';const min=ref.min,max=ref.max,x=i=>55+i*645/Math.max(1,e.series.length-1),y=v=>175-(v-min)*145/(max-min||1);return `<div class="ee-chart-scroll"><svg class="ee-evolution-chart" viewBox="0 0 750 225" role="img" aria-label="Evolución de ${safe(ref.label)}">${[min,(min+max)/2,max].map(v=>`<line x1="55" y1="${y(v)}" x2="700" y2="${y(v)}" stroke="#305166"/><text x="45" y="${y(v)+4}" text-anchor="end" fill="#abc5d4" font-size="11">${eeNumber(v)}</text>`).join('')}${e.series.map((m,i)=>{const v=metrics[i],next=metrics[i+1];return `<text x="${x(i)}" y="205" text-anchor="${i===0?'start':i===e.series.length-1?'end':'middle'}" fill="#d9edf4" font-size="11">${safe(m.wave.slice(0,23))}</text>${v?.value!==null&&v?.value!==undefined?`${next?.value!==null&&next?.value!==undefined?`<line x1="${x(i)}" y1="${y(v.value)}" x2="${x(i+1)}" y2="${y(next.value)}" stroke="#52d4c7" stroke-width="3"/>`:''}<circle cx="${x(i)}" cy="${y(v.value)}" r="5" fill="#f2ca68"><title>${safe(m.wave)}: ${v.value} · ${v.n} personas</title></circle>`:''}`;}).join('')}</svg></div>`;}
function eeEvolutionTable(e,keys){return `<div style="overflow:auto"><table class="ee-evolution-table"><thead><tr><th>Resultado</th>${e.series.map(m=>`<th>${safe(m.wave)}${m.date?'<small>'+safe(m.date)+'</small>':''}</th>`).join('')}<th>Cambio desde ${safe(e.baseline)}</th></tr></thead><tbody>${keys.map(key=>{const comp=e.comparisons.find(v=>v.key===key);return `<tr><td>${safe(comp?.label||key)}</td>${e.series.map(m=>{const metric=m.metrics.find(v=>v.key===key);return `<td>${eeScore(metric?.value,metric)}<small>${safe(eeUnitLabel(metric?.unit))} · ${metric?.n||0} personas</small></td>`;}).join('')}<td>${eeDelta(comp?.delta??null)}<small>${comp?.delta!==null?safe(eeUnitLabel(comp?.unit,true)):''}</small></td></tr>`;}).join('')}</tbody></table></div>`;}
function eeEvolutionResults(x,s){const e=EE.evolution(s,eeFilter.audienceId);if(!e.series.some(m=>m.metrics.some(v=>v.key===eeEvolutionMetric)))eeEvolutionMetric='evo:global';const cards=['evo:nps','evo:global'].map(key=>{const m=e.comparisons.find(v=>v.key===key);return `<article class="ee-metric"><span>${safe(m?.label||key)} · índice de −100 a 100</span><strong class="${eeTone(m?.latestValue,{unit:'puntos'}) .cls}">${eeNumber(m?.latestValue)}<small>índice</small></strong><span class="ee-reading ${eeTone(m?.latestValue,{unit:'puntos'}).cls}">${eeTone(m?.latestValue,{unit:'puntos'}).label}</span><b>${eeDelta(m?.delta??null)}</b><small>Desde ${safe(e.baseline||'la base')} · ${m?.latestN||0} personas en ${safe(e.latest||'la última medición')}</small></article>`;}).join('');const allKeys=[...new Set(e.series.flatMap(m=>m.metrics.map(v=>v.key)))],selected=e.comparisons.find(m=>m.key===eeEvolutionMetric);return `<section class="panel ee-evolution"><div class="flex" style="justify-content:space-between"><div><h2>Así va tu medición</h2><p class="muted">${e.series.length} momentos · ${safe(e.baseline||'Sin base')} → ${safe(e.latest||'Sin mediciones')}</p></div><div class="flex"><button class="primary" onclick="eeSetTab(&quot;importar&quot;)">Añadir medición</button><button class="secondary" onclick="eeExportEvolution()">Descargar evolución</button></div></div>${eeEvolutionFilters(x,s,e)}${e.series.length<2?'<p class="notice">Esta es tu primera medición. Al cargar la siguiente, verás cuánto cambió.</p>':''}<div class="ee-metrics">${cards}</div>${eeColorGuide()}<h3>NPS y Global en el tiempo</h3>${eeEvolutionChart(e,['evo:nps','evo:global'])}${eeEvolutionTable(e,['evo:nps','evo:global'])}<h3>Explora una dimensión o pregunta</h3><label>Resultado<select onchange="eeEvolutionMetric=this.value;render()">${allKeys.map(key=>`<option value="${safe(key)}"${key===eeEvolutionMetric?' selected':''}>${safe(e.comparisons.find(m=>m.key===key)?.label||key)}</option>`).join('')}</select></label><p class="muted">${safe(selected?.label||'Global')} · ${safe(eeUnitLabel(selected?.unit||'puntos'))}</p>${eeMetricChart(e,eeEvolutionMetric)}${eeEvolutionTable(e,[eeEvolutionMetric])}<h3>¿Cómo cambia el grupo?</h3><div class="flex"><span class="ee-positive">Promotores</span><span style="color:#f2ca68">Pasivos</span><span class="ee-negative">Detractores</span></div>${e.series.map(m=>{const g=m.global;return `<div class="ee-evolution-group"><b>${safe(m.wave)}</b><div class="ee-evolution-stack">${[['#8bcc63',g.promoters,g.promotersPercent],['#f2ca68',g.passives,g.passivesPercent],['#ed8b8b',g.detractors,g.detractorsPercent]].map(([color,n,p])=>`<span style="background:${color};width:${p||0}%" title="${n} personas · ${p??0}%">${p>=10?n:''}</span>`).join('')}</div><small>${g.promoters} promotores · ${g.passives} pasivos · ${g.detractors} detractores · ${g.n} personas</small></div>`;}).join('')}${eeCommentsDashboard(s)}<details><summary>Ordenar momentos y elegir la base</summary>${eeMomentSettings(s,e)}</details><details><summary>Ver todas las preguntas y dimensiones</summary>${eeEvolutionTable(e,allKeys.filter(key=>!['evo:nps','evo:global'].includes(key)))}</details><details><summary>Qué debes tener en cuenta</summary><p>La diferencia compara la última medición con la base elegida. Las cantidades de participantes pueden cambiar. No significa que sean las mismas personas ni demuestra por sí sola qué causó el cambio.</p><p>Los resultados se calculan por momento, con las mismas preguntas y escalas de esta encuesta. No mezclamos sus respuestas en un promedio acumulado.</p></details><div class="flex"><button class="secondary" onclick="eeFilter.wave=${JSON.stringify(e.latest).replaceAll('"','&quot;')};render()">Ver detalle de ${safe(e.latest||'la medición')}</button><button class="secondary" onclick="eeExportResponses()">Descargar respuestas</button><button class="secondary" onclick="eeExportSummary()">Resultados completos</button></div></section>`;}
function eeMomentSettings(s,e){return `<form onsubmit="eeSaveMomentSettings(event)"><label>Comparar contra<select name="baseline">${eeOptions(e.series.map(m=>m.wave),e.baseline)}</select></label>${e.series.map((m,i)=>`<div class="grid"><label>${safe(m.wave)} · orden<input name="order_${i}" type="number" min="1" step="1" required value="${i+1}"></label><label>Fecha de medición<input name="date_${i}" type="date" value="${safe(m.date)}"></label></div>`).join('')}<button class="primary">Guardar orden y base</button></form>`;}
function eeSaveMomentSettings(ev){ev.preventDefault();const s=eeSurvey(),e=EE.evolution(s),fd=new FormData(ev.target),settings={},orders=new Set();for(const [i,m] of e.series.entries()){const order=Number(fd.get('order_'+i)),date=String(fd.get('date_'+i)||'');if(!Number.isInteger(order)||order<1||orders.has(order))return eeMsg('Usa un número de orden diferente para cada momento.',true);if(date&&(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))))return eeMsg('Revisa la fecha de medición.',true);orders.add(order);settings[m.wave]={order,date};}s.momentSettings=settings;s.baselineMoment=fd.get('baseline');save();render();eeMsg('Orden y base guardados.');}
function eeExportEvolution(){const s=eeSurvey(),e=EE.evolution(s,eeFilter.audienceId);eeDownload('evolucion-'+s.id+'.csv',EE.csv([['momento','fecha_medicion','audiencia','resultado','valor','unidad','personas','base','cambio_desde_base'],...e.series.flatMap(m=>m.metrics.map(v=>{const base=e.series.find(z=>z.wave===e.baseline)?.metrics.find(z=>z.key===v.key);return [m.wave,m.date,eeFilter.audienceId,v.label,v.value??'',v.unit,v.n,e.baseline,v.value!==null&&base?.value!==null&&base?.value!==undefined?Math.round((v.value-base.value)*100)/100:''];}))]),'text/csv;charset=utf-8');}

function eeTogglePicker(){eePickerOpen=!eePickerOpen;render();}
function eeTone(value,metric={}){if(value===null||value===undefined||!Number.isFinite(Number(value)))return {cls:'ee-tone-empty',label:'Sin datos'};const v=Number(value);if(metric.unit==='puntos')return eeBalanceBand(v);if(!Number.isFinite(metric.min)||!Number.isFinite(metric.max)||metric.min>=metric.max)return {cls:'ee-tone-empty',label:'Sin criterio de color'};let score=(v-metric.min)/(metric.max-metric.min);if(metric.direction==='lower')score=1-score;return score>=.8?{cls:'ee-tone-good',label:'Favorable'}:score>=.6?{cls:'ee-tone-neutral',label:'Intermedio'}:score>=.4?{cls:'ee-tone-watch',label:'Atención'}:{cls:'ee-tone-critical',label:'Crítico'};}
function eeScore(value,metric){const tone=eeTone(value,metric||{});return `<span class="ee-score ${tone.cls}">${eeNumber(value)}<small class="ee-reading ${tone.cls}">${tone.label}</small></span>`;}
function eeDelta(value){const cls=value===null?'ee-tone-empty':value>0?'ee-tone-good':value<0?'ee-tone-critical':'ee-tone-neutral';return `<span class="${cls}">${eeChange(value)}</span>`;}
function eeColorGuide(){return `<details class="ee-color-guide"><summary>Rangos y colores</summary><div class="ee-reading-ranges">${eeBalanceRanges().map(b=>`<article class="${b.cls}"><b>${b.label}</b><small>${b.range}</small><p>${b.description}</p></article>`).join('')}</div><p>Esta escala se usa en NPS, CNPS, Global y balances por dimensión. Es el criterio de lectura de HACERLO. Las flechas indican cuánto subió o bajó; no cambian el nivel del resultado.</p><details><summary>Colores en otras escalas</summary><p>En promedios y porcentajes se conserva la lectura según su rango: favorable desde 80%, intermedio desde 60%, atención desde 40% y crítico por debajo, respetando el sentido de la variable.</p></details></details>`;}
function eeBalanceRanges(){return [{min:-100,max:15,includeMax:false,label:'Crítico',cls:'ee-tone-critical',range:'−100 a menos de 15',description:'Recuperar las condiciones básicas y atender las barreras prioritarias.'},{min:15,max:35,includeMax:false,label:'Alerta',cls:'ee-tone-alert',range:'15 a menos de 35',description:'Revisar qué frena el avance y redefinir las acciones.'},{min:35,max:55,includeMax:false,label:'Acelerar',cls:'ee-tone-accelerate',range:'35 a menos de 55',description:'Reforzar las condiciones para convertir la disposición en acción.'},{min:55,max:75,includeMax:false,label:'Consolidar',cls:'ee-tone-consolidate',range:'55 a menos de 75',description:'Afianzar los avances y corregir los puntos débiles.'},{min:75,max:100,includeMax:true,label:'Sostener',cls:'ee-tone-sustain',range:'75 a 100',description:'Mantener los resultados y extender las prácticas que funcionan.'}];}
function eeBalanceBand(value){if(value===null||value===undefined||value===''||!Number.isFinite(Number(value)))return {cls:'ee-tone-empty',label:'Sin datos'};return eeBalanceRanges().find(b=>Number(value)>=b.min&&(b.includeMax?Number(value)<=b.max:Number(value)<b.max))||{cls:'ee-tone-empty',label:'Fuera de rango'};}

function eeUnitLabel(unit,change=false){if(unit==='puntos')return change?'Cambio del índice':'Índice (−100 a 100)';if(unit==='%')return change?'Cambio en puntos porcentuales':'Porcentaje';return unit||'';}
function eeQuestionResultsSelector(s){return `<details class="ee-detail"><summary>Resultados por pregunta</summary><label>Elige una pregunta<select onchange="eeShowQuestionResult(this.value)"><option value="">Selecciona una pregunta</option>${s.questions.map(q=>`<option value="${safe(q.id)}">${safe(q.label)}</option>`).join('')}</select></label><div id="ee-question-result"><p class="muted">Aquí verás solo la pregunta que elijas.</p></div></details>`;}
function eeOneQuestion(s,id,distributionOnly=false){const q=EE.detailed(s,eeFilter).questions.find(v=>v.questionId===id);if(!q)return '<p class="muted">Selecciona una pregunta.</p>';const balance=EE.composition(s,eeFilter).questions.find(v=>v.questionIds[0]===id);return `<article class="ee-question"><h3>${safe(q.label)}</h3><p class="muted">${q.n} respuestas${q.scoredOptions?' · '+q.scoredN+' con valor · '+q.unscoredN+' sin valor':''}${q.scale?' · escala '+q.scale.join(' a '):''}</p>${distributionOnly?'':`<div class="ee-metrics">${q.mean!==null?`<article class="ee-metric"><span>Promedio</span><strong>${eeNumber(q.mean)}</strong></article>`:''}${balance?`<article class="ee-metric"><span>Balance · índice de −100 a 100</span><strong class="${eeBalanceBand(balance.balance).cls}">${eeNumber(balance.balance)}</strong><span class="ee-reading ${eeBalanceBand(balance.balance).cls}">${eeBalanceBand(balance.balance).label}</span><small>${balance.promoters} promotores · ${balance.passives} pasivos · ${balance.detractors} detractores</small></article>`:q.unit?`<article class="ee-metric"><span>Resultado</span><strong>${eeNumber(q.value)} ${safe(eeUnitLabel(q.unit))}</strong></article>`:''}</div>`}<h4>Cómo respondieron</h4>${q.type==='text'&&!q.scoredOptions?'<p class="muted">Consulta los textos desde Ver comentarios en detalle.</p>':q.distribution.slice().sort((a,b)=>a.answer.localeCompare(b.answer,'es',{numeric:true})).map(v=>`<div class="ee-answer-row"><div><span>${safe(v.answer)}${q.scoredOptions?' · '+(v.score===null?'Sin valor':eeNumber(v.score)):''}</span><b>${v.count} · ${eeNumber(v.percent)}%</b></div><div class="ee-answer-track"><span style="width:${v.percent}%"></span></div></div>`).join('')||'<p class="muted">Sin respuestas para este filtro.</p>'}</article>`;}
function eeShowQuestionResult(id){$('ee-question-result').innerHTML=eeOneQuestion(eeSurvey(),id);}
function eeDistributionSelector(s){return `<details class="ee-detail"><summary>Distribución por pregunta</summary><label>Elige una pregunta<select onchange="eeShowDistribution(this.value)"><option value="">Selecciona una pregunta</option>${s.questions.map(q=>`<option value="${safe(q.id)}">${safe(q.label)}</option>`).join('')}</select></label><div id="ee-distribution-result"><p class="muted">Elige una pregunta para ver sus respuestas.</p></div></details>`;}
function eeShowDistribution(id){$('ee-distribution-result').innerHTML=eeOneQuestion(eeSurvey(),id,true);}
function eeTextSummary(s,filter=eeFilter){const normalize=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),shortAnswers=new Set(['si','no','ninguno','ninguna','nada','na','n/a','no aplica','sin comentarios','ninguna observacion','sin observaciones','ok','bien']),stop=new Set('a al algo alguna algunas algunos ante antes asi aun aunque bajo cada casi como con contra cual cuando de del desde donde durante e el ella ellas ellos en entre era es esa esas ese eso esos esta estaba estaban estar estas este esto estos fue fuera fueron ha habia hacia han hasta hay hice la las le les lo los mas me mi mis misma mismo muy ni no nos nosotros nuestra nuestro o otra otras otro otros para pero por porque pues que quien se sea ser si sido sin sobre son su sus tal tambien tan te tengo tener tiene tienen toda todas todo todos tras tu tus un una unas uno unos usted ustedes va vamos vez ya yo plataforma herramienta conectados crecer experiencia proceso'.split(' '));const entries=[],closed=new Map();s.responses.forEach((r,index)=>{if(filter.wave&&(r.wave||'Base')!==filter.wave||filter.audienceId&&String(r.audienceId)!==String(filter.audienceId))return;for(const q of s.questions.filter(q=>q.type==='text'&&!q.optionScoring?.enabled)){const text=String(r.answers[q.id]??'').trim();if(!text)continue;const n=normalize(text);if(shortAnswers.has(n)){closed.set(n,(closed.get(n)||0)+1);continue;}entries.push({responseId:r.id,responseIndex:index,questionId:q.id,question:q.label,text,wave:r.wave||'Base',respondent:r.respondent||''});}});const counts=new Map();entries.forEach(entry=>{const words=new Set(normalize(entry.text).match(/[a-zñ]{3,}/g)||[]);for(const word of words)if(!stop.has(word))counts.set(word,(counts.get(word)||0)+1);});return {entries,closed:[...closed].map(([label,count])=>({label,count})),words:[...counts].map(([word,count])=>({word,count})).sort((a,b)=>b.count-a.count||a.word.localeCompare(b.word)).slice(0,24),people:new Set(entries.map(e=>e.responseIndex)).size};}
function eeCommentsDashboard(s){const t=eeTextSummary(s),max=t.words[0]?.count||1,participants=s.responses.map((r,i)=>({r,i})).filter(({r})=>(!eeFilter.wave||(r.wave||'Base')===eeFilter.wave)&&(!eeFilter.audienceId||String(r.audienceId)===String(eeFilter.audienceId))&&s.questions.some(q=>q.type==='text'&&String(r.answers[q.id]??'').trim()));return `<section class="panel ee-comments-board"><h3>Lo que cuentan las personas</h3><p class="muted">${t.entries.length} comentarios · ${t.people} participantes con comentarios.</p><div class="ee-word-cloud">${t.words.map(({word,count})=>`<span style="font-size:${14+Math.round(16*count/max)}px" title="Aparece en ${count} comentarios">${safe(word)} <small>${count}</small></span>`).join('')||'<p class="muted">Todavía no hay suficientes palabras para un resumen.</p>'}</div><small class="muted">El número indica en cuántos comentarios aparece la palabra.</small>${t.closed.length?`<details><summary>Respuestas cortas · ${t.closed.reduce((sum,v)=>sum+v.count,0)}</summary><div class="ee-short-answers">${t.closed.map(v=>`<span>${safe(v.label)}: <b>${v.count}</b></span>`).join('')}</div></details>`:''}<details class="ee-detail"><summary>Ver comentarios en detalle</summary><div class="grid"><label>Pregunta<select id="ee-comment-question" onchange="eeUpdateCommentDetail(true)"><option value="">Todas las preguntas</option>${s.questions.filter(q=>q.type==='text').map(q=>`<option value="${safe(q.id)}">${safe(q.label)}</option>`).join('')}</select></label><label>Participante / respuesta<select id="ee-comment-person" onchange="eeUpdateCommentDetail(true)"><option value="">Selecciona un participante o una pregunta</option>${participants.map(({r,i})=>`<option value="${i}">${safe(r.respondent?'Código '+r.respondent:'Respuesta '+(i+1))} · ${safe(r.wave||'Base')}</option>`).join('')}</select></label></div><div id="ee-comment-detail" data-page="0"><p class="muted">Selecciona una pregunta o participante para consultar el detalle.</p></div></details></section>`;}
function eeCommentDetail(s,questionId,personIndex,page=0){if(!questionId&&personIndex==='')return '<p class="muted">Selecciona una pregunta o participante.</p>';const list=[];s.responses.forEach((r,i)=>{if(personIndex!==''&&i!==Number(personIndex)||eeFilter.wave&&(r.wave||'Base')!==eeFilter.wave||eeFilter.audienceId&&String(r.audienceId)!==String(eeFilter.audienceId))return;for(const q of s.questions){if(q.type!=='text'||questionId&&q.id!==questionId)continue;const text=String(r.answers[q.id]??'').trim();if(text)list.push({text,question:q.label,person:r.respondent?'Código '+r.respondent:'Respuesta '+(i+1),wave:r.wave||'Base'});}});const pages=Math.max(1,Math.ceil(list.length/5)),currentPage=Math.max(0,Math.min(page,pages-1));return `<p class="muted">${list.length} comentarios · página ${currentPage+1} de ${pages}</p>${list.slice(currentPage*5,currentPage*5+5).map(e=>`<article class="ee-question"><small>${safe(e.person)} · ${safe(e.wave)}</small><b>${safe(e.question)}</b><p>${safe(e.text)}</p></article>`).join('')||'<p>Sin comentarios para esta selección.</p>'}<div class="flex"><button class="secondary" ${currentPage===0?'disabled':''} onclick="eeCommentPage(${currentPage-1})">Anterior</button><button class="secondary" ${currentPage===pages-1?'disabled':''} onclick="eeCommentPage(${currentPage+1})">Siguiente</button></div>`;}
function eeUpdateCommentDetail(reset=false){const target=$('ee-comment-detail');if(!target)return;const page=reset?0:Number(target.dataset.page||0);target.dataset.page=String(page);target.innerHTML=eeCommentDetail(eeSurvey(),$('ee-comment-question').value,$('ee-comment-person').value,page);}
function eeCommentPage(page){const target=$('ee-comment-detail');target.dataset.page=String(page);eeUpdateCommentDetail();}

function eeOptionScoringPanel(s){return `<section class="panel"><h3>Valores por opción</h3><p class="muted">Asigna un número a cada respuesta. También puedes hacerlo después de importar.</p><label>Pregunta<select onchange="eeShowOptionScoring(this.value)"><option value="">Selecciona una pregunta</option>${s.questions.filter(q=>['text','choice'].includes(q.type)).map(q=>`<option value="${safe(q.id)}">${safe(q.label)}${q.optionScoring?.enabled?' · Con valores':''}</option>`).join('')}</select></label><div id="ee-option-scoring"></div></section>`;}
function eeScoreOptionRow(option='',value=''){return `<div class="grid" data-option-score><label>Opción<input data-option-text value="${safe(option)}" maxlength="5000"></label><label>Valor<input data-option-value type="number" step="any" value="${value}"></label><button type="button" class="secondary" onclick="this.closest('[data-option-score]').remove()">Quitar opción</button></div>`;}
function eeShowOptionScoring(id){const s=eeSurvey(),q=s.questions.find(q=>q.id===id),el=$('ee-option-scoring');if(!q){el.innerHTML='';return;}const c=q.optionScoring||{},options=[...new Set([...(q.options||[]),...(c.options||[]).map(o=>o.option),...s.responses.map(r=>String(r.answers[q.id]??'').trim()).filter(Boolean)])];el.innerHTML=`<form onsubmit="eeSaveOptionScoring(event)"><input name="questionId" type="hidden" value="${safe(id)}"><label><input name="enabled" type="checkbox" ${c.enabled?'checked':''}> Usar valores por opción</label><div class="triple"><label>Mínimo de la escala<input name="min" type="number" step="any" required value="${c.min??0}"></label><label>Máximo de la escala<input name="max" type="number" step="any" required value="${c.max??10}"></label><label>Mejor resultado<select name="direction"><option value="higher"${c.direction!=='lower'?' selected':''}>Un valor más alto</option><option value="lower"${c.direction==='lower'?' selected':''}>Un valor más bajo</option></select></label></div><div id="ee-option-score-rows">${(options.length?options:['','']).map(option=>eeScoreOptionRow(option,c.options?.find(o=>o.option===option)?.value??'')).join('')}</div><button type="button" class="secondary" onclick="eeAddScoreOption()">Añadir opción</button><p class="muted">Una opción sin valor queda fuera del promedio. El texto original se conserva. Los cambios recalculan todos los momentos; no entran automáticamente en NPS ni Global.</p><button class="primary">Guardar valores</button></form>`;}
function eeAddScoreOption(){const el=document.createElement('div');el.innerHTML=eeScoreOptionRow();$('ee-option-score-rows').append(el.firstElementChild);}
async function eeSaveOptionScoring(e){e.preventDefault();const s=eeSurvey(),x=current(),fd=new FormData(e.target),id=fd.get('questionId'),q=s.questions.find(q=>q.id===id);if(!q)return;try{const options=[...e.target.querySelectorAll('[data-option-score]')].flatMap(row=>{const option=row.querySelector('[data-option-text]').value.trim(),raw=row.querySelector('[data-option-value]').value.trim();if(!raw)return [];if(!option)throw Error('Escribe el texto de cada opción con valor.');return [{option,value:Number(raw)}];}),config={enabled:fd.get('enabled')==='on',min:Number(fd.get('min')),max:Number(fd.get('max')),direction:fd.get('direction'),options};EE.validateOptionScoring(config);q.optionScoring=config;s.optionScoringHistory ||= [];s.optionScoringHistory.push({questionId:id,changedAt:EE.now(),config:structuredClone(config)});s.updatedAt=EE.now();eeIntegrate(x,s);save();render();eeMsg('Valores guardados. Puedes ver el promedio y la evolución en Resultados.');}catch(err){eeMsg(err.message,true);}}
